// Flatten a searchable index: one entry per Q&A pair plus one per section (for browsing)
function buildSearchIndex() {
  const idx = [];
  MODULES.forEach(mod => {
    mod.sections.forEach(sec => {
      (sec.qa || []).forEach((item, i) => {
        idx.push({
          type: "qa",
          moduleId: mod.id,
          moduleName: mod.name,
          sectionId: sec.id,
          sectionHeading: sec.heading,
          question: item.q,
          answer: item.a,
          tags: item.tags || [],
          color: mod.color,
          key: `${mod.id}-${sec.id}-${i}`
        });
      });
      idx.push({
        type: "section",
        moduleId: mod.id,
        moduleName: mod.name,
        sectionId: sec.id,
        sectionHeading: sec.heading,
        question: `${sec.heading} — ${mod.name}`,
        answer: sec.html,
        tags: [],
        color: mod.color,
        key: `${mod.id}-${sec.id}-section`
      });
    });
  });
  return idx;
}
